  const started = now(), deadline = started + timeoutMs, cleanupReserve = Math.min(100, timeoutMs * .1);
  const keepAliveSeconds = Math.max(60, Math.ceil(timeoutMs / 1000) + 5);
  const workDeadline = deadline - cleanupReserve;
