if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const result = await runFavoriteMaximaFidelity(maximaFidelityConfiguration(process.argv.slice(2)));
  console.log(JSON.stringify({ directory: result.configuration.directory, comparisons: result.rows.length, additionallyPrunedExecutions: result.additionallyPrunedExecutions, passed: result.passed }));
}

exploration/favorite-optimization-fideli:
// Offline validation of service rankings; never part of the user search path.
import assert from 'node:assert/strict';
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { FAVORITE_METHOD, FAVORITE_PARAMETERS, FAVORITE_WORKLOAD, loadFavoriteScaleInputs } from './favorite-scale-corpus.mjs';
import { loadHueDocuments } from './hue-index.mjs';
import { buildCutoffQuery } from './methods-cutoff.mjs';
import { buildFavoriteOptimizedQuery } from './favorite-optimized-scoring.mjs';
import { FAVORITE_UTILITY_METHODS, buildFavoriteUtilityQuery, favoriteUtilityReference, createFavoriteUtilityPlan, toFavoriteUtilityDocument, quantizeRankFeature } from './favorite-utilities.mjs';
import { api, validateSearchResponse, hash } from './service.mjs';
import { favoriteSourceSnapshot } from './favorite-scale.mjs';

// Fetch the indexed ID from doc values. Reading stored _id can decompress the
// same large stored block as this experiment's multi-megabyte debug _source.
// Query scores and global ordering are untouched; this is validation decoding.
async function searchIndex(index, body) {
  const response = await api(index + '/_search?request_cache=false', { method: 'POST',
    body: { ...body, stored_fields: '_none_', docvalue_fields: ['id'] }, timeoutMs: 10000 });
  for (const hit of response.body.hits?.hits ?? []) {
    assert.equal(hit.fields?.id?.length, 1, 'Expected one indexed document ID');
    hit._id = hit.fields.id[0];
  }
  return { hits: validateSearchResponse(response.body) };
}

export const FIDELITY_QUERIES = [
  ...FAVORITE_WORKLOAD.filter(item => item.selectivity === 'all'),
  ...['#0077ff', '#ff99cc', '#ffffff', '#000000', '#804030'].map(color => ({ id: 'vibe-' + color.slice(1), query: { mode: 'vibe', targets: [{ color }] } })),
  ...['dark', 'grayscale', 'bright'].map(name => ({ id: 'vibe-' + name, query: { mode: 'vibe', targets: [{ name }] } })),
  { id: 'grayscale80-red20', query: { mode: 'proportions', targets: [{ name: 'grayscale', percent: 80 }, { color: '#ff0000', percent: 20 }] } },
  { id: 'grayscale80-red10', query: { mode: 'proportions', targets: [{ name: 'grayscale', percent: 80 }, { color: '#ff0000', percent: 10 }] } },
  { id: 'zero-blue', query: { mode: 'proportions', targets: [{ color: '#0000ff', percent: 0 }, { color: '#ff0000', percent: 50 }] } },
  { id: 'red95', query: { mode: 'proportions', targets: [{ color: '#ff0000', percent: 95 }] } },
];
export function compareFavoriteRankings(reference, actual) {
  assert.equal(actual.length, reference.length);
  assert.equal(new Set(actual.map(hit => hit.id)).size, actual.length);
  const byId = new Map(reference.map((hit, rank) => [hit.id, { ...hit, rank }]));
  const position = new Map(actual.map((hit, rank) => [hit.id, rank]));
  assert.deepEqual([...position.keys()].sort(), [...byId.keys()].sort());
  const deltas = actual.map(hit => Math.abs(hit.score - byId.get(hit.id).score));
  let inversions = 0, meaningfulInversions = 0, largestInversionScoreGap = 0;
  for (let a = 0; a < reference.length; a++) for (let b = a + 1; b < reference.length; b++) {
    if (position.get(reference[a].id) > position.get(reference[b].id)) {
      inversions++;
      const gap = reference[a].score - reference[b].score;
      if (gap > 1e-6) meaningfulInversions++;
      largestInversionScoreGap = Math.max(largestInversionScoreGap, gap);
    }
  }
  const top20 = new Set(reference.slice(0, 20).map(hit => hit.id));
  return { count: actual.length, identicalIds: actual.every((hit, rank) => hit.id === reference[rank].id),
    identicalScores: actual.every(hit => hit.score === byId.get(hit.id).score),
    maximumScoreError: Math.max(0, ...deltas), meanScoreError: deltas.reduce((a, b) => a + b, 0) / Math.max(1, deltas.length),
    top20Overlap: actual.slice(0, 20).filter(hit => top20.has(hit.id)).length,
    maxRankChange: Math.max(0, ...actual.map((hit, rank) => Math.abs(rank - byId.get(hit.id).rank))),
    inversions, meaningfulInversions, meaningfulGapThreshold: 1e-6, largestInversionScoreGap };
}

export function scoreEncodedUtility(document, body) {
  let total = 0;
  for (const term of body.query.bool.should) {
    const feature = term.rank_feature;
    const numeric = term.function_score?.field_value_factor;
    const field = feature?.field ?? numeric.field;
    const [container, key] = field.split('.');
    const value = document[container]?.[key] ?? 0;
    const stored = feature ? quantizeRankFeature(value) : Math.fround(value);
    total += Math.fround(stored * Math.fround(feature?.boost ?? numeric.factor));
  }
  return Math.fround(total);
}

export async function runFavoriteFidelity({ directory, utilityIndex = 'color-exploration-favorite-opt-real-v2', allPresets = true }) {
  await mkdir(path.dirname(directory), { recursive: true }); await mkdir(directory);
  const sourceSnapshot = await favoriteSourceSnapshot(import.meta.url);
  const verified = await loadFavoriteScaleInputs({ scope: 'full', bucketCount: 256 });
  const documents = await loadHueDocuments(256), byId = new Map(documents.map(document => [document.id, document]));
  const baselineIndex = 'color-exploration-shade-hue-256-real-v1';
  for (const index of [baselineIndex, utilityIndex]) assert.equal((await api(index + '/_count')).body.count, 545);
  await writeFile(path.join(directory, 'source-snapshot.json'), JSON.stringify(sourceSnapshot));
  const result = { schemaVersion: 1, startedAt: new Date().toISOString(), sourceSnapshotHash: hash(sourceSnapshot), sourceIdentityHash: verified.identityHash,
    documentValuesHash: hash(documents), count: documents.length, queries: FIDELITY_QUERIES, rows: [],
    limitations: ['All-document service comparisons measure implementation fidelity, not human relevance.', '1e-6 score-gap reporting is a numerical diagnostic, not a perceptual relevance threshold.', 'Validation retrieves indexed IDs through doc values to avoid large stored source blocks; score query, result count and ordering are unchanged. These timings are not a performance benchmark.'] };
  const presets = allPresets ? [0, .5, 1].flatMap(qualityInfluence => [0, 1, 3].map(cutoffBlendExponent => ({ qualityInfluence, cutoffBlendExponent }))) : [{}];
  for (const preset of presets) for (const item of FIDELITY_QUERIES) {
    const parameters = { ...FAVORITE_PARAMETERS, bucketCount: 256, ...preset };
    const baseline = await searchIndex(baselineIndex, buildCutoffQuery({ method: FAVORITE_METHOD, query: item.query, parameters, limit: 1000 }));
    assert.equal(baseline.hits.length, 545);
    const fused = await searchIndex(baselineIndex, buildFavoriteOptimizedQuery({ query: item.query, parameters, limit: 1000 }));
    assert.deepEqual(fused.hits, baseline.hits);
    const rankings = { baseline: baseline.hits, fused: fused.hits };
    // Compile each query's descriptors once. Recompiling the entire color query
    // for every image/method made the validation driver needlessly expensive.
    const encodingPlan = createFavoriteUtilityPlan({ requests: [{ query: item.query, parameters }] });
    const encoded = new Map(documents.map(document => [document.id, toFavoriteUtilityDocument(document, encodingPlan)]));
    for (const method of FAVORITE_UTILITY_METHODS) {
      const body = buildFavoriteUtilityQuery({ method, query: item.query, parameters, limit: 1000 });
      const actual = await searchIndex(utilityIndex, body);
      let maximumOracleError = 0;
      for (const hit of actual.hits) {
        const expected = scoreEncodedUtility(encoded.get(hit.id), body);
        maximumOracleError = Math.max(maximumOracleError, Math.abs(expected - hit.score));
      }
      for (const ordinal of [0, 272, 544]) {
        const document = documents[ordinal];
        assert.equal(scoreEncodedUtility(encoded.get(document.id), body), favoriteUtilityReference(byId.get(document.id), item.query, { method, parameters }));
      }
      assert.ok(maximumOracleError <= 2e-7, `${method.id}: service differs from encoding oracle by ${maximumOracleError}`);
      const comparison = compareFavoriteRankings(baseline.hits, actual.hits);
      const bound = { numeric: 3e-7, rank8: 1 / 510 + 3e-7, rank16: 1 / 131070 + 3e-7, rankfloat: .004 }[method.encoding];
      assert.ok(comparison.maximumScoreError <= bound, `${method.id}: declared numeric bound exceeded`);
      result.rows.push({ queryId: item.id, method: method.id, parameters, maximumOracleError, declaredMaximumScoreError: bound, ...comparison });
      rankings[method.id] = actual.hits;
    }
    await writeFile(path.join(directory, 'rankings.jsonl'), JSON.stringify({ queryId: item.id, parameters, rankings }) + '\n', { flag: 'a' });
    console.log(JSON.stringify({ queryId: item.id, preset, completedComparisons: result.rows.length }));
  }
  assert.equal(hash(await favoriteSourceSnapshot(import.meta.url)), result.sourceSnapshotHash, 'Sources changed during fidelity run');
  result.finishedAt = new Date().toISOString(); result.passed = true;
  await writeFile(path.join(directory, 'fidelity.json'), JSON.stringify(result, null, 2));
  return result;
}
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2), position = args.indexOf('--directory');
  if (position < 0 || !args[position + 1]) throw Error('Provide --directory NEWDIR');
  await runFavoriteFidelity({ directory: path.resolve(args[position + 1]), allPresets: !args.includes('--favorite-only') });
}

exploration/favorite-optimized-scoring.m:
// THROWAWAY PROTOTYPE. Execute the saved favorite in one global OpenSearch
// script, using exactly the original indexed observations and eligibility.
// Pure functions below are extraction/test/diagnostic helpers, never a client
// reranker. No saved favorite source or index is changed by this module.
import { buildCutoffQuery, cutoffParameters, resolveCutoffTargets, supportsCutoff } from './methods-cutoff.mjs';

export const FAVORITE_SOURCE_METHOD = 'cutoff-shade-hue-all-levels';
export const FAVORITE_OPTIMIZED_METHODS = Object.freeze([Object.freeze({
  id: 'favorite-fused-script', label: 'Favorite optimization: fused score',
  description: 'The saved strict-hue five-layer formula executed in one OpenSearch script. Uses existing coverage and quality fields; preserves all controls and global ranking.',
  family: 'favorite-optimized', representation: 'shade-hue-coverage-quality-256', searchKind: 'favorite-optimized',
  approximate: false, sourceMethod: FAVORITE_SOURCE_METHOD, metric: 'shade-hue-aware', profile: 'all-levels',
  limitations: Object.freeze([
    'Retains the saved favorite color measurements, anchor quantization, marginal proportions and lack of an independent outside-color purity penalty.',
    'Reproduces the native factor, weight and component float rounding; exact tied-result parity still depends on the OpenSearch/Lucene scorer implementation and is checked experimentally.',
    'Scoring remains global and scans eligible documents. Fusing scoring machinery is an execution experiment, not a proven scalability improvement.',
  ]),
})]);

const DEFAULT_PARAMETERS = Object.freeze({ bucketCount: 256, cutoffBlendExponent: 1, qualityCurve: 'linear', qualityInfluence: .5 });

function methodFor(input = 'favorite-fused-script') {
  const id = typeof input === 'string' ? input : input?.id;
  const method = FAVORITE_OPTIMIZED_METHODS.find(candidate => candidate.id === id);
  if (!method) throw Error(`Unknown favorite optimized method: ${id}`);
  return method;
}

export function favoriteOptimizedParameters(supplied = {}) {
  if (!supplied || typeof supplied !== 'object' || Array.isArray(supplied)) throw Error('Favorite optimized parameters must be an object.');
  return cutoffParameters(FAVORITE_SOURCE_METHOD, { ...DEFAULT_PARAMETERS, ...supplied });
}

export function supportsFavoriteOptimized(method, query, options = {}) {
  const selected = methodFor(method), parameters = favoriteOptimizedParameters(options.parameters);
  const result = supportsCutoff(FAVORITE_SOURCE_METHOD, query, { ...options, parameters });
  return { ...result, warnings: [...(result.warnings ?? []), ...selected.limitations] };
}

function qualityPlan(parameters, vibe, amount) {
  const qualityApplies = vibe || amount > 0;
  const influence = parameters.qualityInfluence;
  const penalty = vibe ? 1 : parameters.qualityPenalty;
  const strength = penalty * influence;
  let qualityKind = 'none', qualityScale = 0;
  if (qualityApplies && strength !== 0) {
    const nativeLinear = parameters.qualityCurve === 'linear' || influence === 0 || influence === 1 || penalty === 0;
    if (!nativeLinear) qualityKind = 'power';
    else if (vibe && strength === 1) qualityKind = 'direct';
    else {
      qualityKind = 'linear';
      const scale = strength <= 1 ? .5 : .5 / strength;
      const decay = strength <= 1 ? 1 - strength * .5 : .5;
      // Preserve OpenSearch LinearDecayFunctionBuilder.processScale/evaluate
      // order, including rounding. Do not simplify this to 1 / strength.
      qualityScale = scale / (1 - decay);
    }
  }
  return { qualityApplies, qualityRequired: qualityApplies && (influence > 0 || parameters.minimumQuality > 0), qualityKind, qualityScale,
    qualityPenalty: penalty, qualityInfluence: influence, minimumQuality: Math.fround(parameters.minimumQuality) };
}

export function compileFavoriteScorePlan({ query, parameters: supplied = {} }) {
  const parameters = favoriteOptimizedParameters(supplied);
  const { compiled, targets, warnings } = resolveCutoffTargets(FAVORITE_SOURCE_METHOD, query, { parameters });
  const vibe = compiled.mode === 'vibe';
  const components = targets.flatMap(target => target.components.map(component => ({
    ...target, ...component,
    vibe, weight: Math.fround(component.componentWeight / targets.length), origin: Math.round(target.amount * 10000),
    areaFactor: Math.fround(.0001), areaPower: parameters.areaPower,
    underScale: 5000 / .5, overScale: (5000 / parameters.excessPenalty) / .5,
    ...qualityPlan(parameters, vibe, target.amount),
  })));
  return { parameters, compiled, targets, warnings, components };
}

function requiredMeasurement(document, field) {
  if (!Object.hasOwn(document, field) || !Number.isFinite(document[field])) throw Error(`Missing or non-finite favorite measurement: ${field}`);
  return document[field];
}

// Numeric details modeled on OpenSearch 2.11.0 FieldValueFactorFunction,
// LinearDecayFunctionBuilder, WeightFactorFunction and FunctionScoreQuery.
// https://github.com/opensearch-project/OpenSearch/tree/2.11.0/server/src/main/java/org/opensearch/common/lucene/search/function
export function scoreFavoriteComponent(document, component) {
  const coverage = requiredMeasurement(document, component.coverageField);
  const quality = component.qualityRequired ? Math.fround(requiredMeasurement(document, component.qualityField)) : 0;
  if (component.qualityApplies && component.minimumQuality > 0 && quality < component.minimumQuality) return 0;
  let area;
  if (component.vibe) {
    area = coverage * component.areaFactor;
    if (component.areaPower === .5) area = Math.sqrt(area);
  } else {
    const scale = coverage <= component.origin ? component.underScale : component.overScale;
    area = Math.max(0, (scale - Math.abs(coverage - component.origin)) / scale);
  }
  let factor = 1;
  if (component.qualityKind === 'direct') factor = quality;
  else if (component.qualityKind === 'linear') factor = Math.max(0, (component.qualityScale - Math.abs(1 - quality)) / component.qualityScale);
  else if (component.qualityKind === 'power') factor = Math.pow(Math.max(0, Math.min(1, 1 - component.qualityPenalty * (1 - quality))), component.qualityInfluence);
  return Math.fround(area * factor * component.weight);
}

export function scoreFavoriteReference(document, plan) {
  return Math.fround(plan.components.reduce((score, component) => score + scoreFavoriteComponent(document, component), 0));
}

// Keep the source constant across colors, target counts and quality controls.
// Stored scripts/compilation caches can therefore reuse one compiled program.
export const FAVORITE_FUSED_SCRIPT = `
double total = 0.0;
boolean vibe = (boolean)params.vibe;
boolean squareRoot = (boolean)params.squareRoot;
double areaFactor = ((Number)params.areaFactor).doubleValue();
double underScale = ((Number)params.underScale).doubleValue();
double overScale = ((Number)params.overScale).doubleValue();
double minimumQuality = ((Number)params.minimumQuality).doubleValue();
double qualityScale = ((Number)params.qualityScale).doubleValue();
double qualityPenalty = ((Number)params.qualityPenalty).doubleValue();
double qualityInfluence = ((Number)params.qualityInfluence).doubleValue();
int qualityKind = ((Number)params.qualityKind).intValue();
for (int i = 0; i < params.coverageFields.size(); ++i) {
  double coverage = ((Number)doc[(String)params.coverageFields.get(i)].value).doubleValue();
  boolean qualityApplies = (boolean)params.qualityApplies.get(i);
  double quality = 0.0;
  if ((boolean)params.qualityRequired.get(i)) {
    quality = ((Number)doc[(String)params.qualityFields.get(i)].value).doubleValue();
  }
  if (qualityApplies && minimumQuality > 0.0 && quality < minimumQuality) continue;
  double area;
  if (vibe) {
    area = coverage * areaFactor;
    if (squareRoot) area = Math.sqrt(area);
  } else {
    double origin = ((Number)params.origins.get(i)).doubleValue();
    double scale = coverage <= origin ? underScale : overScale;
    area = Math.max(0.0, (scale - Math.abs(coverage - origin)) / scale);
  }
  double qualityFactor = 1.0;
  if (qualityApplies) {
    if (qualityKind == 1) qualityFactor = quality;
    else if (qualityKind == 2) qualityFactor = Math.max(0.0, (qualityScale - Math.abs(1.0 - quality)) / qualityScale);
    else if (qualityKind == 3) qualityFactor = Math.pow(Math.max(0.0, Math.min(1.0, 1.0 - qualityPenalty * (1.0 - quality))), qualityInfluence);
  }
  double weight = ((Number)params.weights.get(i)).doubleValue();
  total += (float)(area * qualityFactor * weight);
}
return (float)total;
`;

export function buildFavoriteOptimizedQuery({ method = 'favorite-fused-script', query, parameters: supplied = {}, ...options }) {
  methodFor(method);
  const plan = compileFavoriteScorePlan({ query, parameters: supplied });
  const native = buildCutoffQuery({ ...options, method: FAVORITE_SOURCE_METHOD, query, parameters: plan.parameters });
  // Use a positive target to obtain the shared quality formula, since a zero
  // target disables quality for that term but must not disable other terms.
  const quality = qualityPlan(plan.parameters, plan.compiled.mode === 'vibe', 1);
  const first = plan.components[0];
  const params = {
    vibe: first.vibe, squareRoot: plan.parameters.areaPower === .5,
    areaFactor: first.areaFactor, underScale: first.underScale, overScale: first.overScale,
    minimumQuality: quality.minimumQuality, qualityScale: quality.qualityScale,
    qualityPenalty: quality.qualityPenalty, qualityInfluence: quality.qualityInfluence,
    qualityKind: ['none', 'direct', 'linear', 'power'].indexOf(quality.qualityKind),
    coverageFields: plan.components.map(component => component.coverageField),
    qualityFields: plan.components.map(component => component.qualityField),
    origins: plan.components.map(component => component.origin),
    weights: plan.components.map(component => component.weight),
    qualityRequired: plan.components.map(component => component.qualityRequired),
    qualityApplies: plan.components.map(component => component.qualityApplies),
  };
  return { ...native, query: { script_score: {
    query: { bool: { filter: native.query.bool.filter } },
    script: { lang: 'painless', source: FAVORITE_FUSED_SCRIPT, params },
  } } };
}

exploration/favorite-precision-utilities:
// THROWAWAY refinement: retain the favorite's complete precomputed utility,
// encoding it in two/three exactly representable base512 rank-feature limbs.
// All user filtering and ranking happen globally inside OpenSearch.
import {
  FAVORITE_UTILITY_METHODS, FAVORITE_UTILITY_DEFINITION, createFavoriteUtilityPlan,
  supportsFavoriteUtilities, favoriteUtilityRankField, toFavoriteUtilityDocument,
  buildFavoriteUtilityQuery,
} from './favorite-utilities.mjs';

const ENCODINGS = Object.freeze({ rank18: Object.freeze({ limbs: 2, scale: 262143 }), rank27: Object.freeze({ limbs: 3, scale: 134217727 }) });
const original = FAVORITE_UTILITY_METHODS.find(method => method.encoding === 'numeric');
export const FAVORITE_PRECISION_METHODS = Object.freeze(Object.entries(ENCODINGS).map(([encoding, settings]) => Object.freeze({
  id: 'favorite-utility-' + encoding, encoding,
  label: `Favorite256: indexed utility, split ${encoding.slice(4)}-bit`,
  description: `The favorite's complete precomputed utility rounded to ${settings.scale + 1} levels and stored as ${settings.limbs} base512 rank features.`,
  family: 'favorite-precision-utilities', representation: 'favorite256-precomputed-utilities', searchKind: 'favorite-precision-utilities',
  approximate: false, objectiveApproximation: true,
  retrieval: 'Exact global ranking for the stored utility objective',
  objectivePrecision: `Target utility rounding error at most ${.5 / settings.scale} before query float32 multiplication and addition.`,
  limitations: Object.freeze([...original.limitations,
    `Each utility uses ${settings.limbs} nonnegative base512 digits, each no greater than 511 and exactly representable as a rank feature. Zero digits are omitted.`,
    'Additional stored precision does not avoid float32 query arithmetic or the changed grouping relative to the original five-layer query.']),
})));
export const FAVORITE_PRECISION_DEFINITION = Object.freeze({
  version: 1, parentUtilityDefinitionVersion: FAVORITE_UTILITY_DEFINITION.version,
  snapshot: 'strict-hue-favorite-001', encodings: ENCODINGS, base: 512,
  utility: FAVORITE_UTILITY_DEFINITION.utility,
  fieldLayout: 'Separate rank_features fields per encoding and quality/cutoff-weight preset; two or three positive digit features per complete target utility.',
  zero: FAVORITE_UTILITY_DEFINITION.zero,
  precision: 'Fixed-point digit quantization plus float32 query boosts/products/sum. Formula and observations stay unchanged at offered presets.',
});

export function favoritePrecisionMethod(input = 'favorite-utility-rank18') {
  const id = typeof input === 'string' ? input : input?.id;
  const method = FAVORITE_PRECISION_METHODS.find(candidate => candidate.id === id);
  if (!method) throw Error('Unknown favorite precision method: ' + id);
  return method;
}
function encodingFor(encoding) {
  if (!Object.hasOwn(ENCODINGS, encoding)) throw Error('Unsupported precision encoding: ' + encoding);
  return ENCODINGS[encoding];
}
function validateEncodings(encodings) {
  if (!Array.isArray(encodings) || !encodings.length || new Set(encodings).size !== encodings.length) throw Error('Use distinct nonempty precision encodings.');
  for (const encoding of encodings) encodingFor(encoding);
