  const targetKey = target.kind === 'region' ? 'r' + String(target.regionIndex).padStart(4, '0') : 'n_' + target.name;
  const amountKey = mode === 'vibe' ? 'v' : 'p' + String(Math.round(target.amount * 100)).padStart(3, '0');
