  } else {
    if (!Array.isArray(presets) || presets.length === 0) throw Error('A full utility plan requires at least one preset.');
    const targets = [...overlapRegionsForCount(256).map(region => ({ color: region.hex })), ...FEATURE_NAMES.map(name => ({ name }))];
