  const normalized = Math.sqrt(distanceSquared(lab, region.lab)) / OVERLAP_DEFINITION.radius;
  return normalized <= 1 + 1e-12 ? { area: 1, quality: 1 - (1 - OVERLAP_DEFINITION.edgeWeight) * Math.min(1, normalized) } : { area: 0, quality: 0 };
