  } catch (error) { return failure(error.message); }
}

function channels(rgb) {
  const [r, g, b] = rgb;
  const max = Math.max(r, g, b), min = Math.min(r, g, b), delta = max - min;
  const l = (max + min) / 2;
  const h = delta < 1e-8 ? null : (((max === r ? (g - b) / delta : max === g ? (b - r) / delta + 2 : (r - g) / delta + 4) / 6) % 1 + 1) % 1;
