    } else {
      for (const key of { rgb: ['r', 'g', 'b'], hsv: ['h', 's', 'v'], hsl: ['h', 's', 'l'] }[range.space]) {
        let distance;
        if (key === 'h') {
          if (range.h === 1) continue;
          if (anchor[range.space].h == null) throw new Error('Achromatic anchors require hue distance 100%.');
