}
function mixPalette(a,b,weight,total){
  const cells=[...a.map(p=>({rgb:Math.floor(p/65536),count:(p%65536)*weight})),...b.map(p=>({rgb:Math.floor(p/65536),count:(p%65536)*(1-weight)}))];
